import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_DIGITS = "0123456789"


def _text(row, key):
    value = row.get(key, "")
    return "" if value is None else str(value)


def _is_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _norm_email(raw):
    """Return the normalized email if valid, otherwise ""."""
    value = raw
    m = re.search(r"<([^<>]*)>", value)
    if m:
        value = m.group(1)
    value = value.strip().lower()
    if value.count("@") != 1:
        return ""
    local, domain = value.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return f"{local}@{domain}"


def _norm_phone(raw):
    """Return the normalized 10-digit phone if valid, otherwise ""."""
    value = raw.lower()
    markers = [i for i in (value.find("x"), value.find("ext"), value.find("#")) if i != -1]
    if markers:
        value = value[:min(markers)]
    digits = "".join(c for c in value if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    value = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", value)
    if m:
        value = m.group(1)
    if len(value) == 4 and _is_digits(value):
        value = "0" + value
    if len(value) == 5 and _is_digits(value):
        return value
    return ""


def _norm_name(raw):
    value = raw.strip()
    if value.isupper() or value.islower():
        value = value.title()
    return value


def _parse_updated(raw):
    value = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return raw.strip().lower() in {"y", "yes", "true", "1"}


def _norm_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def _pick_value(group, field):
    """Choose the field value: manual rows first, then most recent updated, then earliest row."""
    cands = [r for r in group if r[field]]  # group is in input order
    if not cands:
        return ""
    ordered = sorted(cands, key=lambda r: r["updated"], reverse=True)  # stable: ties keep input order
    ordered.sort(key=lambda r: not r["manual"])  # stable: manual rows first
    return ordered[0][field]


def _merge(group):
    tags = sorted(set().union(*(r["tags"] for r in group)))
    return {
        "first_name": _pick_value(group, "first_name"),
        "last_name": _pick_value(group, "last_name"),
        "zip": _pick_value(group, "zip"),
        "email": _pick_value(group, "email"),
        "phone": _pick_value(group, "phone"),
        "source": _pick_value(group, "source"),
        "tags": ";".join(tags),
        "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
        "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    # Normalize rows and drop any without a valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _norm_email(_text(row, "email"))
        phone = _norm_phone(_text(row, "phone"))
        if not email and not phone:
            continue
        source_raw = _text(row, "source").strip()
        records.append({
            "idx": idx,
            "first_name": _norm_name(_text(row, "first_name")),
            "last_name": _norm_name(_text(row, "last_name")),
            "zip": _norm_zip(_text(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source_raw.lower(),
            "manual": source_raw.lower() == "manual",
            "tags": _norm_tags(_text(row, "tags")),
            "opted_out": _is_opted_out(_text(row, "opted_out")),
            "updated": _parse_updated(_text(row, "updated")),
        })

    # Union-find over records to handle transitive matches.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(records):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Group rows; dict insertion order follows each group's earliest row.
    groups = {}
    for i, r in enumerate(records):
        groups.setdefault(find(i), []).append(r)

    return [_merge(group) for group in groups.values()]
```

Notes on the implementation:

- **Opt-outs:** The output's `opted_out` flag is "Y" if any row in a person's group opted out. Filter out `opted_out == "Y"` before the send. Rows with no valid email or phone are dropped before matching, so they never appear in the output.
- **ZIP+4 with a dropped leading zero:** I treat `2139-4307` as ZIP+4 (4-digit prefix plus 4 digits) and pad it to `02139`. Your rules didn't say whether that case should count as ZIP+4, so check it against the data person's intent.
- **Bad `updated` values:** Unrecognized dates raise a `ValueError` rather than being silently sorted as oldest, so one malformed row can't quietly change which record wins. Wrap the call if you'd rather skip those rows.
